mapper.select:
SELECT t.task_id, t.parent_task_id, p.project_name, t.title, t.assignee_user_id, u.user_name, t2.type_name, t.progress_rate, t.start_date, t.due_date FROM tasks t LEFT JOIN projects p ON t.project_id = p.project_id LEFT JOIN task_types t2 ON t.task_type_id = t2.task_type_id LEFT JOIN users u ON t.assignee_user_id = u.user_id
AND (t.project_id = #{projectId} OR p.parent_project_id = #{projectId})
AND t.title LIKE '%' || #{title} || '%'
AND t.assignee_user_id = #{assigneeUserId}
AND t.task_type_id = #{taskTypeId}
AND t.start_date >= #{startDate}
AND t.due_date <= #{dueDate}
ORDER BY t.start_date DESC
